{
  "tools": [
    {
      "name": "get_selection",
      "title": "Get Selection",
      "toolset": "scene",
      "description": "What's selected in the editor - the game objects and components the user (or you) has picked.",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "GameObjects": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Id": {
                  "type": "string"
                },
                "Name": {
                  "type": "string"
                }
              },
              "required": []
            }
          },
          "Components": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Id": {
                  "type": "string"
                },
                "Type": {
                  "type": "string"
                },
                "GameObject": {
                  "type": "string"
                }
              },
              "required": []
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "hammer_assign_asset",
      "title": "Assign Asset",
      "toolset": "hammer",
      "description": "Apply an asset to nodes the way dropping it onto them in Hammer does - a material paints every face of the meshes (or just the selected faces, in Faces mode), a model swaps a prop's model. Give node ids, or nothing to apply to the current selection. Selects the nodes it applied to. The user can undo this.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "asset": {
            "type": "string",
            "description": "The material or model asset path."
          },
          "ids": {
            "type": "array",
            "items": {
              "type": "integer"
            },
            "description": "Node ids to apply to. Empty applies to the current selection."
          }
        },
        "required": [
          "asset"
        ]
      }
    },
    {
      "name": "hammer_focus_nodes",
      "title": "Focus Nodes",
      "toolset": "hammer",
      "description": "Select nodes and frame every Hammer view on them, like the user pressing the frame selection key - the quickest way to show the user something, or to aim hammer_screenshot at it.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "ids": {
            "type": "array",
            "items": {
              "type": "integer"
            },
            "description": "The node ids to frame."
          }
        },
        "required": [
          "ids"
        ]
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Mode": {
            "type": "string"
          },
          "Pivot": {
            "type": "string"
          },
          "Count": {
            "type": "integer"
          },
          "Nodes": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Id": {
                  "type": "integer"
                },
                "Kind": {
                  "type": "string"
                },
                "Name": {
                  "type": "string"
                },
                "ClassName": {
                  "type": "string"
                },
                "Description": {
                  "type": "string"
                },
                "Position": {
                  "type": "string"
                },
                "Parent": {
                  "type": "integer"
                },
                "GameObject": {
                  "type": "string"
                },
                "Selected": {
                  "type": "boolean"
                },
                "Visible": {
                  "type": "boolean"
                }
              },
              "required": []
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "hammer_get_node",
      "title": "Get Node",
      "toolset": "hammer",
      "description": "Everything about one map node - transform, parent and children, and depending on its kind: an entity's class and every keyvalue, a mesh's face materials, a game object's id and components, or an instance's target.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "id": {
            "type": "integer",
            "description": "The node id, from hammer_find_nodes or hammer_get_selection."
          },
          "includeComponentProperties": {
            "type": "boolean",
            "description": "Include the full serialized properties of a game object's components, not just their types.",
            "default": false
          }
        },
        "required": [
          "id"
        ]
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Angles": {
            "type": "string"
          },
          "Scale": {
            "type": "string"
          },
          "ChildCount": {
            "type": "integer"
          },
          "Children": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Id": {
                  "type": "integer"
                },
                "Kind": {
                  "type": "string"
                },
                "Name": {
                  "type": "string"
                },
                "ClassName": {
                  "type": "string"
                },
                "Description": {
                  "type": "string"
                },
                "Position": {
                  "type": "string"
                },
                "Parent": {
                  "type": "integer"
                },
                "GameObject": {
                  "type": "string"
                },
                "Selected": {
                  "type": "boolean"
                },
                "Visible": {
                  "type": "boolean"
                }
              },
              "required": []
            }
          },
          "EntityClassTitle": {
            "type": "string"
          },
          "KeyValues": {
            "type": "object",
            "additionalProperties": {
              "type": "string"
            }
          },
          "Materials": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "Components": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Type": {
                  "type": "string"
                },
                "Id": {
                  "type": "string"
                },
                "Enabled": {
                  "type": "boolean"
                },
                "Properties": {}
              },
              "required": []
            }
          },
          "Tags": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "InstanceTarget": {
            "type": "integer"
          },
          "Id": {
            "type": "integer"
          },
          "Kind": {
            "type": "string"
          },
          "Name": {
            "type": "string"
          },
          "ClassName": {
            "type": "string"
          },
          "Description": {
            "type": "string"
          },
          "Position": {
            "type": "string"
          },
          "Parent": {
            "type": "integer"
          },
          "GameObject": {
            "type": "string"
          },
          "Selected": {
            "type": "boolean"
          },
          "Visible": {
            "type": "boolean"
          }
        },
        "required": []
      }
    },
    {
      "name": "hammer_get_selection",
      "title": "Get Selection",
      "toolset": "hammer",
      "description": "What's selected in Hammer - the selection mode (Groups, Objects, Meshes, Vertices, Edges, Faces...), the pivot position, and the selected nodes. In a component mode like Faces the nodes list is the objects owning the selection.",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Mode": {
            "type": "string"
          },
          "Pivot": {
            "type": "string"
          },
          "Count": {
            "type": "integer"
          },
          "Nodes": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Id": {
                  "type": "integer"
                },
                "Kind": {
                  "type": "string"
                },
                "Name": {
                  "type": "string"
                },
                "ClassName": {
                  "type": "string"
                },
                "Description": {
                  "type": "string"
                },
                "Position": {
                  "type": "string"
                },
                "Parent": {
                  "type": "integer"
                },
                "GameObject": {
                  "type": "string"
                },
                "Selected": {
                  "type": "boolean"
                },
                "Visible": {
                  "type": "boolean"
                }
              },
              "required": []
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "hammer_list_commands",
      "title": "List Commands",
      "toolset": "hammer",
      "description": "Hammer's named commands - everything its key bindings and menus can do, like GroupSelection, HideUnselected, SelectSimilar, MirrorHorizontal, SnapToGrid, CreatePrefabFromSelection, FrameAllViews or BuildMap. Run one with hammer_run_command.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "query": {
            "type": "string",
            "description": "Case insensitive substring to filter by, e.g. 'select' or 'prefab'. Empty lists all."
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "hammer_run_command",
      "title": "Run Command",
      "toolset": "hammer",
      "description": "Run a Hammer command by name, exactly as if the user pressed its key binding. Most act on the selection, so select first with hammer_select - e.g. select nodes then run GroupSelection. A few open dialogs and will wait for the user. hammer_list_commands lists them all.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "The command name, as hammer_list_commands shows it."
          }
        },
        "required": [
          "name"
        ]
      }
    },
    {
      "name": "hammer_select",
      "title": "Select",
      "toolset": "hammer",
      "description": "Change Hammer's selection - select nodes by id and/or everything using an asset, optionally switching selection mode first. Selecting is how you show the user what you mean, and some tools (hammer_run_command, hammer_assign_asset) act on the selection. Returns the new selection.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "ids": {
            "type": "array",
            "items": {
              "type": "integer"
            },
            "description": "Node ids to select. Empty selects nothing by id."
          },
          "usingAsset": {
            "type": "string",
            "description": "Also select every node using this asset - a model or material path."
          },
          "add": {
            "type": "boolean",
            "description": "Add to the current selection instead of replacing it.",
            "default": false
          },
          "mode": {
            "type": "string",
            "enum": [
              "Groups",
              "Objects",
              "Meshes",
              "Verticies",
              "Edges",
              "Faces",
              "Nav",
              "Tiles"
            ],
            "description": "Switch selection mode first - Groups, Objects or Meshes. Empty keeps the current mode."
          }
        },
        "required": []
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Mode": {
            "type": "string"
          },
          "Pivot": {
            "type": "string"
          },
          "Count": {
            "type": "integer"
          },
          "Nodes": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Id": {
                  "type": "integer"
                },
                "Kind": {
                  "type": "string"
                },
                "Name": {
                  "type": "string"
                },
                "ClassName": {
                  "type": "string"
                },
                "Description": {
                  "type": "string"
                },
                "Position": {
                  "type": "string"
                },
                "Parent": {
                  "type": "integer"
                },
                "GameObject": {
                  "type": "string"
                },
                "Selected": {
                  "type": "boolean"
                },
                "Visible": {
                  "type": "boolean"
                }
              },
              "required": []
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "hammer_status",
      "title": "Status",
      "toolset": "hammer",
      "description": "Whether Hammer is open and what map it's editing - the map's asset path, unsaved changes, how many nodes of each kind it has, the selection mode and count, and the material active in Hammer's material browser. Start here before any other hammer_ tool. If Hammer isn't open, hammer_open_map opens a map in it.",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Open": {
            "type": "boolean"
          },
          "MapOpen": {
            "type": "boolean"
          },
          "Map": {
            "type": "string"
          },
          "File": {
            "type": "string"
          },
          "HasUnsavedChanges": {
            "type": "boolean"
          },
          "NodeCounts": {
            "type": "object",
            "additionalProperties": {
              "type": "integer"
            }
          },
          "SelectionMode": {
            "type": "string"
          },
          "SelectedCount": {
            "type": "integer"
          },
          "CurrentMaterial": {
            "type": "string"
          },
          "ViewCount": {
            "type": "integer"
          }
        },
        "required": []
      }
    },
    {
      "name": "set_selection",
      "title": "Set Selection",
      "toolset": "scene",
      "description": "Replace the editor selection. Selecting something highlights it for the user - useful for showing them what you're talking about. An empty list clears the selection.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "ids": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "Game object or component ids to select."
          }
        },
        "required": [
          "ids"
        ]
      }
    }
  ],
  "total": 128
}
